// Identical to Case 1's parser and the router's, so the same Twilio payload is
// read the same way wherever it lands.
const b = $json.body || $json;
const rawFrom = (b.From || b.from || '').toString();
const phone = rawFrom.replace(/^whatsapp:/i, '').replace(/[\s\-()]/g, '').trim();
let message = (b.Body || b.body || '').toString().trim();
const sid = (b.MessageSid || b.SmsMessageSid || b.SmsSid || '').toString();

// ---------------------------------------------------------------------------
// MEDIA (added 2026-09-01, found by the FIRST voice note ever sent to Case 2).
//
// The router gained placeholder substitution on 2026-08-21, but it forwards the
// ORIGINAL Twilio payload by design - its own note says "the handler must not be
// able to tell" - so that substitution NEVER reaches this workflow. Each handler
// has to do its own media handling.
//
// This parser still carried the pre-2026-08-21 rule `skip = (!phone || !message)`,
// and a WhatsApp voice note arrives with an EMPTY Body and NumMedia>=1. So every
// voice note to Case 2 was silently dropped: no cart_messages row, no Slack, no
// holding reply. The customer answered and got silence, and the comment above
// claimed this parser matched the router's while it had not since 2026-08-21.
//
// Voice notes are a dominant WhatsApp modality in the Gulf and Levant. This was a
// hole on the customer-facing path, not an edge case.
// ---------------------------------------------------------------------------
const numMedia = parseInt((b.NumMedia || b.numMedia || '0').toString(), 10) || 0;
const mediaType = (b.MediaContentType0 || '').toString().toLowerCase();
const hasMedia = numMedia > 0;
let mediaKind = null;
if (hasMedia) {
  if (mediaType.indexOf('audio') === 0) mediaKind = 'voice';
  else if (mediaType.indexOf('image') === 0) mediaKind = 'image';
  else if (mediaType.indexOf('video') === 0) mediaKind = 'video';
  else if (mediaType.indexOf('application/pdf') === 0) mediaKind = 'document';
  else mediaKind = 'attachment';
  if (!message) {
    const label = { voice: '[voice note]', image: '[image]', video: '[video]', document: '[document]', attachment: '[attachment]' };
    message = label[mediaKind];
  }
}

const skip = (!phone || !message);

return [{ json: {
  inbound_phone: phone,
  inbound_message: message,
  inbound_sid: sid,
  has_media: hasMedia,
  media_kind: mediaKind,
  media_type: mediaType || null,
  num_media: numMedia,
  skip: skip
} }];

const inbound = $('Parse Inbound Message').first().json;
const resp = $input.first().json;
const httpCode = (resp && resp.statusCode) ? resp.statusCode : 0;
const body = resp ? resp.body : null;

const lookupOk = (httpCode === 200 && Array.isArray(body));
// ---------------------------------------------------------------------------
// PICK THE CART THAT OWNS THE CONVERSATION, do not trust the first row.
//
// MUST stay identical to pickCart in the router's `Decide Route`. If the router
// forwards on cart X and this node acts on cart Y, the system answers a
// conversation it did not route. n8n Code nodes cannot import a shared module,
// so the duplication is deliberate - the same reason fmtMoney and register_zone
// below are duplicated from workflow 02 - and tests/resolve-reply-context.test.js
// asserts the two status lists still match.
//
// Here the bug was a COMPLIANCE failure, not just a routing one. `route` is
// derived from the chosen cart and `Suppress Cart` acts on it, so with
// `limit=1` a customer holding an active cart A and a newer CONVERTED cart B
// who replied `توقف` had cart B suppressed - already closed, sending nothing -
// while cart A carried on messaging them, and the run log called it a success.
// Found live 2026-09-02.
// ---------------------------------------------------------------------------
const CASE2_STATUSES = ['pending_verification', 'abandoned', 'recovering', 'exhausted'];

function pickCart(list) {
  if (!list || !list.length) return null;
  // 1. A cart that still owns the conversation, most recent first.
  const live = list.filter(function (r) {
    return CASE2_STATUSES.indexOf(r.status) >= 0 && r.opted_out !== true;
  }).sort(function (a, b) {
    return Date.parse(b.created_at) - Date.parse(a.created_at);
  });
  if (live.length) return live[0];
  // 2. A suppressed cart, so a repeat STOP is still swallowed by us.
  const supp = list.filter(function (r) { return r.opted_out === true; })
    .sort(function (a, b) { return Date.parse(b.created_at) - Date.parse(a.created_at); });
  if (supp.length) return supp[0];
  // 3. Otherwise the most recent closed row, kept for context and logging.
  return list.slice().sort(function (a, b) {
    return Date.parse(b.created_at) - Date.parse(a.created_at);
  })[0];
}

const cart = lookupOk ? pickCart(body) : null;

// ---- money, formatted in code exactly as workflow 02 does it -----------------
// Style guide 3.1 (Hussein, 2026-08-04): Western digits, thousands separators,
// currency code AFTER the number, no pointless decimals. Used in the Slack
// notification so the owner sees the same figure the customer was quoted.
function fmtMoney(amount, currency) {
  const cur = String(currency || '').toUpperCase();
  if (amount === null || amount === undefined || amount === '') return cur;
  const n = Number(amount);
  if (!isFinite(n)) return String(amount) + (cur ? ' ' + cur : '');
  const ZERO_DECIMAL = ['LBP','IQD','JPY','KRW','VND','CLP','ISK'];
  const zero = ZERO_DECIMAL.indexOf(cur) >= 0;
  const hasCents = Math.abs(n - Math.round(n)) > 0.004;
  const dp = (zero || !hasCents) ? 0 : 2;
  return (cur ? (n.toLocaleString('en-US', { minimumFractionDigits: dp, maximumFractionDigits: dp }) + ' ' + cur)
              : n.toLocaleString('en-US', { minimumFractionDigits: dp, maximumFractionDigits: dp }));
}

// ---- register zone, same rule as Build Touch Message Request ----------------
const LEVANT_EGYPT = ['LB','JO','SY','PS','EG'];
const GULF = ['AE','SA','QA','KW','BH','OM'];
const cc = String((cart && cart.country_code) || '').toUpperCase();
const register_zone = LEVANT_EGYPT.indexOf(cc) >= 0 ? 'levant_egypt'
                    : (GULF.indexOf(cc) >= 0 ? 'gulf' : 'other');

// ---- opt-out keywords, checked BEFORE any model call ------------------------
// We instruct the customer to reply STOP / توقف, so obeying that instruction has
// to work every time, not usually. Matched on the whole trimmed message and on a
// leading word, so "STOP" and "stop please" both count while "don't stop sending
// me these, they're useful" does not.
const msg = (inbound.inbound_message || '').trim();
// Quote characters are stripped as well as punctuation. The touch-1 opt-out
// line now reads لإيقاف الرسائل، أرسل "توقف" (canonical wording,
// arabic-master-reference.md §8.5), so the keyword the customer is shown is QUOTED - and
// copying it back verbatim is the most likely way for them to send it. Without
// this, "توقف" would fail both the exact-match and the prefix test and a
// genuine opt-out would be treated as an ordinary reply. Compliance control:
// it must not depend on the customer stripping our own punctuation.
const normalised = msg.toLowerCase().replace(/[.!،؟?"'«»“”„‘’‹›]/g, ' ').replace(/\s+/g, ' ').trim();
const KEYWORDS = ['stop', 'unsubscribe', 'arret', 'arrêt', 'arretez', 'arrêtez',
                  '\u062A\u0648\u0642\u0641',            // توقف
                  '\u0627\u0644\u063A\u0627\u0621',      // الغاء
                  '\u0625\u0644\u063A\u0627\u0621'];     // إلغاء
let keywordHit = null;
for (const k of KEYWORDS) {
  if (normalised === k || normalised.indexOf(k + ' ') === 0) { keywordHit = k; break; }
}

// ---- route ------------------------------------------------------------------
let route = 'classify';
if (!cart) route = 'no_match';
else if (cart.opted_out === true) route = 'already_suppressed';
else if (keywordHit) route = 'opt_out_keyword';

const items = (cart && Array.isArray(cart.cart_items)) ? cart.cart_items : [];
const named = items.slice(0, 2).map(function (i) { return (i.title || 'item') + ' \u00d7' + (i.quantity || 1); });
const extra = items.length - named.length;

return [{ json: {
  route: route,
  lookup_ok: lookupOk,
  lookup_status_code: httpCode,
  has_cart: !!cart,
  keyword_hit: keywordHit,
  cart_id: cart ? cart.id : null,
  checkout_token: cart ? cart.checkout_token : null,
  cart_status: cart ? cart.status : null,
  touches_sent: cart ? cart.touches_sent : null,
  next_touch_at: cart ? cart.next_touch_at : null,
  customer_first_name: cart ? cart.customer_first_name : null,
  phone: inbound.inbound_phone,
  language: (cart && ['ar','en','fr','mixed'].indexOf(cart.language) >= 0) ? cart.language : 'en',
  country_code: cart ? cart.country_code : null,
  register_zone: register_zone,
  items_summary: named.join('; ') + (extra > 0 ? ('; and ' + extra + ' more') : ''),
  item_count: items.length,
  total_display: cart ? fmtMoney(cart.cart_total, cart.currency) : null,
  recovery_url: cart ? cart.recovery_url : null,
  inbound_message: msg,
  inbound_sid: inbound.inbound_sid,

  // Carried through for the holding-reply rule (ruled 2026-09-01). The parser
  // derives these from NumMedia / MediaContentType0 on the raw Twilio payload.
  has_media: inbound.has_media === true,
  media_kind: inbound.media_kind || null
} }];

const VALID = ['wants_to_buy', 'question', 'opt_out', 'other'];

let intent = 'other';
let reason = null;
let degraded = true;
let detail = 'no_response';

try {
  const data = $input.first().json;
  const d = (data && data.body) ? data.body : data;
  if (d && Array.isArray(d.content)) {
    const tb = d.content.find(function (b) { return b && b.type === 'text' && b.text; });
    if (tb) {
      const raw = tb.text.toString().trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
      const parsed = JSON.parse(raw);
      if (parsed && VALID.indexOf(parsed.intent) >= 0) {
        intent = parsed.intent;
        reason = (parsed.reason || '').toString().slice(0, 120);
        degraded = false;
        detail = null;
      } else {
        detail = ('unexpected_intent: ' + JSON.stringify(parsed).slice(0, 120));
      }
    }
  } else if (d && d.error) {
    detail = ('api_error: ' + JSON.stringify(d.error)).slice(0, 200);
  }
} catch (e) { detail = 'parse_error'; }

// A message we could not read is one a human should answer. Defaulting to
// 'other' notifies the owner with the raw text and sends the customer NOTHING -
// a holding reply promising a callback is a commitment not worth making on a
// guess, and defaulting to opt_out would silently kill a live sequence.
return [{ json: {
  intent: intent,
  intent_reason: reason,
  intent_degraded: degraded,
  intent_detail: detail,
  intent_source: degraded ? 'default_fallback' : 'model'
} }];

const c = $('Resolve Reply Context').first().json;
const patch = $input.first().json;
const pb = (patch && patch.body !== undefined) ? patch.body : patch;
const rows = Array.isArray(pb) ? pb.length : 0;

const tlang = (c.language === 'mixed') ? 'ar' : c.language;

// STATIC templates, not generated. One sentence confirming suppression carries
// no personalisation worth a model call, and it is a compliance artefact that
// must read identically every time.
//
// ALL THREE now describe PHONE-level suppression. Until 2026-09-02 every string
// said "about this cart", which was accurate while a STOP suppressed one cart
// and became an understatement the moment suppression moved to the phone.
//
// ARABIC: the vetted [OK] opt-out confirmation from arabic-master-reference.md
// 8.5, adopted verbatim 2026-09-02 (6b.1 reopened). A fixed glossary string
// (rule 0.2): never regenerate, paraphrase or inflect it. There is deliberately
// NO register branch - a fixed string reads identically in every message.
// Written raw rather than \u-escaped, matching the FALLBACK templates in
// workflow 02's Parse Touch Message: escapes are for the regex markers, raw
// Arabic for customer-facing copy a reviewer has to be able to read.
//
// EN and FR: rewritten 2026-09-03. arabic-master-reference.md has no opt-out
// confirmation in either language, so there was nothing to adopt - its EN/FR
// table (8.7) covers waitlist and no-show only, and 8.9 covers the keywords a
// customer TYPES, not the confirmation sent back. Per 8.7 these carry no
// vetting gate; Hussein reads them. The edit is deliberately minimal: only the
// cart-scoping clause changed, so the existing voice is preserved.
//
// The French keeps the impersonal "C'est note" opening on purpose. The natural
// alternative, "vous etes desinscrit", takes a gendered past participle
// (desinscrit / desinscrite) and we do not reliably know the customer's gender
// here - the same trap the Arabic gender rules exist to avoid. "de notre part"
// scopes the promise to this store: without it the sentence claims we can stop
// messages we do not send.
const AR_OPTOUT = 'تم إيقاف الرسائل. شكراً لك';

const TEXT = {
  ar: AR_OPTOUT,
  en: 'You have been unsubscribed. We will not message you again.',
  fr: "C'est noté : vous ne recevrez plus de messages de notre part."
};

return [{ json: {
  rows_updated: rows,
  already_suppressed: rows === 0,
  confirmation_text: TEXT[tlang] || TEXT.en,
  language: c.language,
  register_zone: c.register_zone
} }];

const c = $('Resolve Reply Context').first().json;
const i = $('Parse Intent').first().json;

const tlang = (c.language === 'mixed') ? 'ar' : c.language;
const name = c.customer_first_name || '(no name)';

// A holding reply is sent only when the customer asked something a human will
// answer. 'other' (a thumbs-up, a wrong number, or a message the classifier
// could not read) gets no automated reply - promising a callback for an emoji
// is worse than silence.
//
// MEDIA ALWAYS GETS A HOLDING REPLY. Ruled by Hussein 2026-09-01, after the first
// voice note ever sent to Case 2 produced a Slack notification and NOTHING to the
// customer. The rule above is right for a thumbs-up or a wrong number - we cannot
// read it, so we promise nothing. A voice note is categorically different: the
// customer unambiguously COMMUNICATED, we simply cannot transcribe it, and Haiku
// correctly returns 'other' saying exactly that. Silence there is the same defect
// we had just fixed one layer up, only later in the pipeline.
//
// The holding text claims only that the message reached the team and will be
// answered - which for a media inbound is literally true, because the Slack
// notification below is what makes it true. It commits to no time, price or
// availability. Voice notes are a dominant WhatsApp modality in the Gulf and the
// Levant, so this is a common path, not an edge case.
const needsHolding = (i.intent === 'wants_to_buy' || i.intent === 'question' || c.has_media === true);

// STATIC per-language holding text. Nothing here is personalised, and it must
// never invent a commitment (a time, a price, an availability). Arabic register
// per prompts/arabic-style-guide.md 1.2; no إن شاء الله for timing (3).
// ⚠ v1 wording, NOT yet reviewed by Hussein.
const AR_LEVANT = '\u0634\u0643\u0631\u0627\u064B \u0644\u0631\u0633\u0627\u0644\u0629 \u062D\u0636\u0631\u062A\u0643. \u0648\u0635\u0644\u062A \u0625\u0644\u0649 \u0641\u0631\u064A\u0642\u0646\u0627 \u0648\u0633\u064A\u062A\u0645 \u0627\u0644\u0631\u062F \u0639\u0644\u064A\u0647\u0627 \u0641\u064A \u0623\u0642\u0631\u0628 \u0648\u0642\u062A.';
const AR_PLAIN  = '\u0634\u0643\u0631\u0627\u064B \u0644\u0631\u0633\u0627\u0644\u062A\u0643. \u0648\u0635\u0644\u062A \u0625\u0644\u0649 \u0641\u0631\u064A\u0642\u0646\u0627 \u0648\u0633\u064A\u062A\u0645 \u0627\u0644\u0631\u062F \u0639\u0644\u064A\u0647\u0627 \u0641\u064A \u0623\u0642\u0631\u0628 \u0648\u0642\u062A.';

const HOLDING = {
  ar: (c.register_zone === 'levant_egypt') ? AR_LEVANT : AR_PLAIN,
  en: 'Thanks for your message. Our team has it and will reply shortly.',
  fr: "Merci pour votre message. Notre \u00e9quipe l'a bien re\u00e7u et vous r\u00e9pondra rapidement."
};

const ICON = { wants_to_buy: '\ud83d\uded2', question: '\u2753', other: '\ud83d\udcac' };
const HEAD = {
  wants_to_buy: 'wants to buy',
  question: 'has a question',
  other: 'replied'
};

// ---------------------------------------------------------------------------
// SLACK LAYOUT - restructured 2026-09-08 on Hussein's instruction. Two changes,
// both about how this is actually read: the owner sees it on a phone, in a
// channel, and answers on WhatsApp.
//
// 1. BLOCK KIT instead of one long mrkdwn paragraph. The old message put the
//    name, phone, cart, status and intent on five lines of running text, which
//    is fine on a laptop and unreadable in a notification. A header carries who
//    and what, the quote carries the customer's own words, and the rest sits in
//    two-column fields that stay aligned on a narrow screen.
//
// 2. THE PHONE IS A wa.me LINK. It used to be a bare E.164 string, so answering
//    meant copy, switch app, paste. The `+` MUST be stripped from the path -
//    https://wa.me/+961... 404s while https://wa.me/961... opens the thread.
//    The `+` is kept in the LABEL, because that is the number the owner reads.
//
// `slack_text` is no longer the message. It is the fallback Slack shows in the
// sidebar, in a push notification and on a locked screen, so it stays short and
// names the customer.
// ---------------------------------------------------------------------------
const digits = String(c.phone || '').replace(/[^0-9]/g, '');
const waLink = digits ? ('<https://wa.me/' + digits + '|' + c.phone + '>') : '(no phone on the cart)';

const headline = name + ' ' + (HEAD[i.intent] || 'replied');

const fields = [
  { type: 'mrkdwn', text: '*WhatsApp*\n' + waLink },
  { type: 'mrkdwn', text: '*Intent*\n' + (ICON[i.intent] || '\ud83d\udcac') + ' ' + i.intent +
      (i.intent_degraded ? '  \u26a0 fallback' : '') },
  { type: 'mrkdwn', text: '*Cart*\n' + (c.items_summary || '(unknown items)') },
  { type: 'mrkdwn', text: '*Value*\n' + (c.total_display || '(unknown total)') },
  { type: 'mrkdwn', text: '*Status*\n' + c.cart_status + ' \u00b7 touch ' + c.touches_sent + ' of 3 sent' },
  { type: 'mrkdwn', text: '*Language*\n' + c.language }
];

const blocks = [
  // plain_text, so the header must stay emoji-free - the icon lives in the
  // Intent field and in the notification fallback instead.
  { type: 'header', text: { type: 'plain_text', text: headline, emoji: false } },
  { type: 'section', text: { type: 'mrkdwn', text: '> ' + String(c.inbound_message || '').replace(/\n/g, '\n> ') } },
  { type: 'section', fields: fields }
];

if (c.recovery_url) {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '<' + c.recovery_url + '|Open the customer\u2019s cart>' } });
}

// The classifier's reasoning goes in a context line rather than a field: it is
// useful when the owner disagrees with the intent, and noise the rest of the
// time. A degraded classification is stated in words, never implied by absence.
const why = (i.intent_reason ? ('Classifier: ' + i.intent_reason) : 'Classifier: no reason given') +
  (i.intent_degraded ? '  \u26a0 classifier unavailable, intent defaulted' : '');
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: why }] });

return [{ json: {
  needs_holding_reply: needsHolding,
  holding_text: HOLDING[tlang] || HOLDING.en,
  slack_text: (ICON[i.intent] || '\ud83d\udcac') + ' ' + headline + '  \u2014  ' + (c.phone || 'no phone'),
  slack_blocks: blocks,
  intent: i.intent
} }];
